CREATE TABLE period_fiscal_years (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, status TEXT NOT NULL DEFAULT 'OPEN', UNIQUE(company_id,id), CHECK(start_date<=end_date), CHECK(status IN ('OPEN','CLOSED')));
CREATE INDEX period_fiscal_year_range ON period_fiscal_years(company_id,start_date,end_date);
CREATE TABLE period_accounting_periods (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, fiscal_year_id TEXT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, status TEXT NOT NULL DEFAULT 'OPEN', UNIQUE(company_id,id), CONSTRAINT period_year_fk FOREIGN KEY(company_id,fiscal_year_id) REFERENCES period_fiscal_years(company_id,id) ON DELETE RESTRICT, CHECK(start_date<=end_date), CHECK(status IN ('OPEN','CLOSED')));
CREATE INDEX period_accounting_range ON period_accounting_periods(company_id,fiscal_year_id,start_date,end_date);
CREATE TABLE period_fiscal_close_history (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, fiscal_year_id TEXT NOT NULL, close_journal_id TEXT NOT NULL, reversal_journal_id TEXT, closed_at TIMESTAMPTZ NOT NULL, reopened_at TIMESTAMPTZ, CONSTRAINT period_close_year_fk FOREIGN KEY(company_id,fiscal_year_id) REFERENCES period_fiscal_years(company_id,id) ON DELETE RESTRICT, UNIQUE(company_id,fiscal_year_id,close_journal_id));
CREATE TABLE gl_accounts (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, code TEXT NOT NULL, name TEXT NOT NULL, classification TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT true, postable BOOLEAN NOT NULL DEFAULT true, parent_id TEXT, control_type TEXT, UNIQUE(company_id,id), UNIQUE(company_id,code), CONSTRAINT gl_account_parent_fk FOREIGN KEY(company_id,parent_id) REFERENCES gl_accounts(company_id,id) ON DELETE RESTRICT, CHECK(classification IN ('ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE')));
CREATE TABLE gl_journals (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, number TEXT NOT NULL, posting_date DATE NOT NULL, kind TEXT NOT NULL, source_type TEXT NOT NULL, source_id TEXT NOT NULL, request_hash TEXT NOT NULL, correlation_id TEXT, reversal_of_id TEXT UNIQUE, fiscal_year_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id,id), UNIQUE(company_id,number), UNIQUE(company_id,source_type,source_id), CONSTRAINT gl_reversal_fk FOREIGN KEY(reversal_of_id) REFERENCES gl_journals(id) ON DELETE RESTRICT);
CREATE INDEX gl_journal_date ON gl_journals(company_id,posting_date);
CREATE TABLE gl_journal_lines (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, journal_id TEXT NOT NULL, account_id TEXT NOT NULL, debit DECIMAL(38,18), credit DECIMAL(38,18), party_id TEXT, foreign_amount DECIMAL(38,18), foreign_currency TEXT, fx_rate_id TEXT, fx_rate DECIMAL(38,18), CONSTRAINT gl_line_journal_fk FOREIGN KEY(company_id,journal_id) REFERENCES gl_journals(company_id,id) ON DELETE RESTRICT, CONSTRAINT gl_line_account_fk FOREIGN KEY(company_id,account_id) REFERENCES gl_accounts(company_id,id) ON DELETE RESTRICT, CHECK(((debit IS NOT NULL AND debit>0 AND (credit IS NULL OR credit=0)) OR (credit IS NOT NULL AND credit>0 AND (debit IS NULL OR debit=0)))));
CREATE INDEX gl_line_journal ON gl_journal_lines(company_id,journal_id);
CREATE INDEX gl_line_account ON gl_journal_lines(company_id,account_id);
